def replace_once(text: str, old: str, new: str, rel: str) -> str:
    if old not in text:
        raise RuntimeError(
            f"Expected patch pattern not found in {rel}. "
            "Your local repository differs from base commit 7ff6a67; "
            "aborting rather than applying a partial model change."
        )
    return text.replace(old, new, 1)

def main() -> None:
    root = Path(
        sys.argv[1] if len(sys.argv) > 1 else "."
    ).resolve()

    if not (root / "sim").is_dir() or not (root / "ui").is_dir():
        raise SystemExit(
            f"{root} does not look like the Metalwork repository root."
        )

    backup = root / ".chatgpt_relaxation_root_fix_backup"
    backup.mkdir(exist_ok=True)

    edited = {}
    for rel, reps in REPLACEMENTS.items():
        path = root / rel
        text = path.read_text(encoding="utf-8")
        for old, new in reps:
            text = replace_once(text, old, new, rel)
        edited[rel] = text

    paths = set(FULL_FILES) | set(edited)
    for rel in sorted(paths):
        src = root / rel
        if src.exists():
            dst = backup / rel
            dst.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(src, dst)

    for rel, content in FULL_FILES.items():
        dst = root / rel
        dst.parent.mkdir(parents=True, exist_ok=True)
        dst.write_text(content, encoding="utf-8")

    for rel, content in edited.items():
        (root / rel).write_text(content, encoding="utf-8")

    print("Applied root-cause relaxation/control/physics fixes.")
    print(f"Backup: {backup}")
    print()
    print("Validate:")
    print("  python -m pytest")
    print("  cd ui")
    print("  npm run build")
    print()
    print("Restart FastAPI and Vite after applying.")

if __name__ == "__main__":
    main()
